function proto(gatedir)
addpath(gatedir); addpath('src'); addpath(gatedir);
md = cvt_model('doppler');
k = (1:1500)';
truth = [0.5 * k, -0.2 * k, 0.5 * ones(1500, 1), -0.2 * ones(1500, 1)];
