for g = {0, -1, Inf, NaN, [5.991 9.210]}
  [acc, d2] = measurement_gate([0.1; 0.1], eye(2), g{1});
  assert(~acc && isinf(d2), 'T8 fail closed on bad gamma');
end
n = n + 1;

